.urgent-notice-container {
    width: 100%;
    background-color: var(--color6);
    color: var(--color7);
    padding: 50px 70px;
/*     border-radius: 5px; */
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: left;
    max-width: 100%;
}

.urgent-notice-content {
    display: flex;
    align-items: center;
    gap: 40px;
    width: 100%;
    max-width: 1200px;
    justify-content: space-between;
}

.urgent-notice-icon img {
    width: 35px;
    height: auto;
}

.urgent-notice-text {
    font-size: 1.5rem;
    font-weight: normal;
}

.urgent-notice-text strong {
    font-weight: bold;
}

.urgent-notice-button {
    margin-left: auto;
}

.notice-button {
    background-color: var(--color7);
    color: var(--color2) !important;
    font-weight: bold;
    text-decoration: none;
    padding: 8px 50px;
    border-radius: 5px;
	font-size: 20px;
    display: inline-block;
    transition: all 0.3s ease-in-out;
}

.notice-button:hover {
    background-color: var(--color2);
    color:var(--color7) !important;
    text-decoration: none!important;
	font-style: normal!important;
}

/* Responsive (Stack on smaller screens) */
@media screen and (max-width: 768px) {
    .urgent-notice-content {
        flex-direction: column;
        text-align: center;
        align-items: center;
    }

    .urgent-notice-button {
        margin-left: 0;
        margin-top: 10px;
    }
}
/*# sourceURL=https://tax.idaho.gov/wp-content/themes/Webmaster-v4/inc/its-blocks/urgent-notice/urgent-notice.css */


/* Ensure consistent spacing for grid */
.featured-services-container {
  margin-top: 20px;
  margin-bottom: 20px;
}

/* If only 3 items, make them spread across full width */
.featured-services-container.three-items .service-box {
  flex: 1 1 33%;
  max-width: 33%;
}

/* Ensure consistent styling for service boxes */
.featured-services-container .service-box .card {
  border: none;
  overflow: hidden;
  transition: transform 0.3s ease-in-out;
}

.featured-services-container .service-box img {
  width: 100%;
  height: auto !important;
  object-fit: cover;
}

.featured-services-container .service-box .card-title {
  font-size: 1.5rem;
  font-weight: 700 !important;
  margin: 0px;
  background: var(--color1);
  padding: 10px;
  margin-top: 0 !important;
  border-radius: 0 !important;
  transition: all 0.2s ease-in-out;
}

.featured-services-container .service-box .card-title:hover {
  font-size: 1.5rem;
  margin: 0;
  background: var(--color2);
  padding: 10px;
  color: #fff;
  border-radius: 0 !important;
}

.featured-services-container .card {
  margin-bottom: 30px;
  position: relative;
  border-radius: 0 !important;
}

.featured-services-container .card-body.text-center {
  padding: 0;
}

.featured-services-container .service-box .card-title a {
  color: var(--color1);
  text-decoration: none;
  font-weight: 700;
  font-size: 20px;
}

.featured-services-container .service-box .card-title a:hover {
  text-decoration: none;
  font-style: normal;
  color: var(--color7) !important;
}

/* Responsive Adjustments */
@media screen and (max-width: 1024px) {
  .featured-services-container .service-box {
    max-width: 50%;
    flex: 1 1 50%;
  }
}

@media screen and (max-width: 768px) {
  .featured-services-container .service-box {
    max-width: 100%;
    flex: 1 1 100%;
  }
}

.featured-services-container .card-img-top {
  height: 100% !important;
}

/*# sourceURL=https://tax.idaho.gov/wp-content/themes/Webmaster-v4/inc/its-blocks/featured-services/featured-services.css */


.cta-section {
    width: 100%;
    background-color: var(--color3);
    color: var(--color7);
    padding: 0px;
    text-align: center;
    max-width: 100%;
    margin: auto;
    display: flex;
    flex-direction: column;
    align-items: center;
}

.cta-content {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    flex-grow: 1; /* Allows content to take up space */
    width: 100%;
    max-width: 700px;
	padding: 70px;
	gap: 0px
}

.cta-icon img {
    width: 60px;
    height: auto;
    margin-bottom: 10px;
}

.cta-title {
    color: var(--color7);
    font-size: 1.5rem;
    font-weight: bold;
    margin: 10px 0;
}

.cta-description {
    font-size: 1rem;
	margin-bottom: 0px;
/* 	color: #555555!important; */
}

/* Full-width button styling */
.cta-button {
    background-color: var(--color2);
    color: var(--color7);
    font-weight: bold;
    text-decoration: none;
    padding: 12px;
    display: block;
    text-align: center;
    width: 100%;
    max-width: 100%;
    border-radius: 0;
	font-size: 20px;
    transition: background 0.3s ease-in-out;
}

a.cta-button:hover {
	font-style: normal!important;
}

.cta-button:hover {
    background-color: var(--color7);
	color: var(--color2);
    text-decoration: none;
}

/* Responsive Adjustments */
@media screen and (max-width: 768px) {
    .cta-section {
        padding: 0;
    }

    .cta-title {
        font-size: 1.3rem;
    }

    .cta-button {
        padding: 12px;
        width: 100%; /* Button stretches full width */
        border-radius: 0;
    }
}
/*# sourceURL=https://tax.idaho.gov/wp-content/themes/Webmaster-v4/inc/its-blocks/cta-block-vertical/cta-top-icon.css */


.featured-services-solid-container {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 20px;
    width: 100%;
    margin: auto;
    padding: 50px 0;
}

.featured-services-solid-container .service-box-solid {
    background-color: var(--color3);
    overflow: hidden;
    text-align: center;
    padding: 50px 20px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: space-between;
    transition: transform 0.3s ease-in-out;
}

.featured-services-solid-container .service-icon img {
    width: 80px;
    height: auto;
    margin-bottom: 15px;
}

.featured-services-solid-container .service-title {
    font-size: 2.5rem;
    font-weight: bold;
    margin-bottom: 10px;
	color: var(--color7);
}

.featured-services-solid-container .service-description {
    font-size: 1rem;
    margin-bottom: 20px;
    color: var(--color7);
}

/* Button Styling */
.featured-services-solid-container .service-button {
    background-color: var(--color7);
    color: var(--color2);
    font-weight: bold;
    text-decoration: none;
    padding: 12px 20px;
    border-radius: 4px;
    display: inline-block;
    transition: background 0.3s ease-in-out;
}

.featured-services-solid-container .service-button:hover {
    background-color: var(--color2);
    color: var(--color7) !important;
    text-decoration: none;
}

/* Responsive Design */
@media screen and (max-width: 1024px) {
    .featured-services-solid-container {
        grid-template-columns: repeat(2, 1fr); /* Show 2 per row */
    }
}

@media screen and (max-width: 768px) {
    .featured-services-solid-container {
        grid-template-columns: repeat(1, 1fr); /* Stack on small screens */
    }
}
