    color: #0077B3 !important;
}

table#tablepress-159 td.column-2,
table#tablepress-159 td.column-3,
table#tablepress-159 td.column-4 {
    text-align: center;
}

.icon-card .elementor-element.elementor-button-info .elementor-button {
    background-color: #0077b3;
    border: 0.15rem solid #0077b3;
}

.elementor-icon i, .elementor-icon svg {
    width: 1em;
    height: 1em;
    position: relative;
    display: block;
    margin-left: auto;
    margin-right: auto;
}

.h4,h4,.h5,h5 {
    font-weight: normal;
}

.elementor-alert > .elementor-alert-description > p > a,
.elementor-alert > .elementor-alert-description > ol > li > a {
    text-decoration: underline;
}

.searchandfilter ul li ul li ul {
    margin-left: -10px;
}

.mec-wrap {
    color: #1a1a1a;
}

#top-navigation .nav-link {
    color: white !important;
    padding: .25rem .7rem !important;
    background-color: #0077b3;
    border-radius: 4px;
    font-size: 13px;
}

#top-navigation .nav-link:hover {
    background-color: #447d46 !important;
    text-decoration: none !important;
}

.attachment-full {height: auto;}
.mec-event-more-info {display:none;}

.skip-link, .sr-only {color:blue; background:white;}

.icon-card {
    position:relative;
    z-index:1;
}

/* Equal-height icon-box widgets — scoped to specific pages so it doesn't affect
   standalone icon-boxes elsewhere.
   200686 = Popular Credits and Deductions
   882    = Individual Income Tax Basics (online-guide) */
.page-id-200686 .elementor-widget-icon-box,
.page-id-200686 .elementor-widget-icon-box > .elementor-widget-container,
.page-id-882 .elementor-widget-icon-box,
.page-id-882 .elementor-widget-icon-box > .elementor-widget-container {
    height: 100%;
}

.icon-card .elementor-icon-box-icon {
    margin-top: -3em;
    padding: 1em;
    max-height: 10em;
}

/* Pin the button to the bottom of icon-card columns so buttons line up across the row.
   Elementor already sets .elementor-widget-wrap to display: flex, so we only override
   flex-direction here and let its natural column stretching equalize heights. */
.elementor-column.icon-card .elementor-widget-wrap {
