        jumpnav = false;
        
        function build_sspy_link(sspydata) {
            let sspylink = document.createElement('li')
            sspylink.classList.add('sspylink')
            let anchorlink = document.createElement('a')
            anchorlink.classList.add('sspyanchorlink')
            anchorlink.classList.add('dot')
            anchorlink.setAttribute('href', "#" + sspydata.anchor)
            anchorlink.innerHTML = sspydata.title
            jQuery(anchorlink).attr('data-scroll', sspydata.anchor)
            sspylink.appendChild(anchorlink);
            return sspylink;
        }

        function build_sspy_list_item(sspydata) {
            let sspylink = document.createElement('option')
            sspylink.classList.add('sspylink')
            sspylink.classList.add('sspyanchorlink')
            sspylink.classList.add('dot')
            sspylink.innerHTML = sspydata.title
            jQuery(sspylink).attr('value', sspydata.anchor);
            jQuery(sspylink).attr('data-scroll', sspydata.anchor)
            return sspylink;
        }
        jQuery(function($) {
            let mitems = {}
            let lis = "";
            let cblocks = $('section.elementor-top-section:not(.page-section)')

            if (cblocks.length > 16)
                jumpnav = true;
            if (jumpnav) {
                $(".sspy-container").find('nav').append("<select style='' id='scrollspyjumper' name=scrollspy value='' aria-label='select section to jump to'></select>")
            }
            cblocks.toArray().forEach(function(el, indx) {
                let title = $(el).find('h2').text();
                let randomid = indx;
                $(el).attr('id', randomid)
                if (title) {
                    mitems[indx] = {}
                    mitems[indx]['title'] = title;
                    mitems[indx]['anchor'] = $(el).attr('id');
                    if (!jumpnav)
                        $(".sspy-container").find('ul').append(build_sspy_link(mitems[indx]))
                    else {
                        $("#scrollspyjumper").append(build_sspy_list_item(mitems[indx]))
                    }
                }
            })
            if (($('#sspy-menu').find('ul').find("li").length < 2) && ($('#sspy-menu').find('select').find("option").length < 2))
                $("#sspy-menu").hide();
            else
                $("#sspy-menu").show();

            var bch = $(".breadcrumb").outerHeight(true)
            var na = $(".notice-area").height();
            var tn = $(".top-navigation").height();
            var bcpos = $(".breadcrumb").offset().top

            $("#sspy-menu").css("top", na + tn + bch + bcpos + "px")

            $(window).scroll(() => {
                topOfFooter = $('.site-footer').offset().top - 240;
                scrollDistanceFromTopOfDoc = $(document).scrollTop() + $("#sspy-menu ul").height() * 2;
                scrollDistanceFromTopOfFooter = scrollDistanceFromTopOfDoc - topOfFooter;
                if (scrollDistanceFromTopOfDoc > topOfFooter) {
                    $("#sspy-menu ul").css('margin-top', 0 - scrollDistanceFromTopOfFooter);
                } else {
                    $("#sspy-menu ul").css('margin-top', 0);
                }
            });

            const box = document.getElementById('sspylinks');
            if (box.children.length === 0) {
                $('.onthispage-container').hide()
            } else {
                $('.onthispage-container').show()
            }

        });

        jQuery(function($) {
            var link = $('#sspy-menu a.dot');
            if (!jumpnav) {
                link.on('click', function(e) {
                    var target = $($(this).attr('href'));
                    $(this).addClass('active');
                });
            } else {
                link = $('#scrollspyjumper');
                link.on('change', function(e) {
                    var target = $(this).val();
                    element_to_scroll_to = document.getElementById(target);
                    element_to_scroll_to.scrollIntoView();
                });
            }
            $(window).on('scroll', function() {
                scrNav();
            });

            function scrNav() {
                var sTop = $(window).scrollTop();
                $('section').each(function() {
                    var id = $(this).attr('id'),
                        offset = parseInt($(this).offset().top),
                        height = $(this).height();
                    if (sTop >= (offset - 100) && sTop < offset + height) {
                        if (!jumpnav) {
                            link.removeClass('active');
                            $('#sspy-menu').find('[data-scroll="' + id + '"]').addClass('active');
                        } else {
                            $(link).find('option[selected]').removeAttr('selected');
                            $('#sspy-menu').find('[data-scroll="' + id + '"]').attr('selected');
                            $('#sspy-menu').find('[data-scroll="' + id + '"]').closest('select').val(id)
                        }
                    }
                });
            }
            scrNav();
        });
     


 

   
     
       
               
       
         
           
             
               
                 
